function zones(age, rhr){
  age=+age; rhr=+rhr; if(!(age>0)||!(rhr>0)) return {error:'年龄与静息心率须为正'};
  var maxHR=220-age, hrr=maxHR-rhr;
  var bands=[[0.5,0.6,'热身区'],[0.6,0.7,'燃脂区'],[0.7,0.8,'有氧区'],[0.8,0.9,'无氧区'],[0.9,1.0,'极限区']];
  var out=[]; for(var i=0;i<bands.length;i++){ var lo=Math.round(rhr+bands[i][0]*hrr), hi=Math.round(rhr+bands[i][1]*hrr);
    out.push({name:bands[i][2], lo:lo, hi:hi}); }
  return {maxHR:maxHR, hrr:hrr, zones:out};
}
var EXPORTS={zones:zones};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeartRateZoneForgePure = EXPORTS; }
